import re,csv,glob,os
from collections import defaultdict

def parse_doc(path):
    t=open(path,encoding='utf-8').read().strip()
    d={}
    for part in re.split(r'[；;]',t):
        part=part.strip()
        if not part: continue
        m=re.match(r'([^:：\s]+)[:：\s]\s*(.*)',part)
        if m: d[m.group(1)]=m.group(2).strip().rstrip('。')
    m=re.search(r'第(\d+)日至第(\d+)日',d['有效期'])
    return dict(obj=d['对象'],flow=int(d['签发流水']),cat=d['类别'],signer=d['签发人'],
                start=int(m.group(1)),end=int(m.group(2)),station=d['主站'])
docs=[parse_doc(p) for p in glob.glob('inbox/06-02/签署附件/*/*.txt')]
roster={r['对象']:r['授权签发人'] for r in csv.DictReader(open('inbox/06-02/值班签发名册.csv',encoding='utf-8-sig'))}
def station_for(obj,biz=2):
    cand=[x for x in docs if x['obj']==obj and x['cat']=='正式' and roster.get(obj)==x['signer'] and x['start']<=biz<=x['end']]
    cand.sort(key=lambda x:(x['start'],x['flow']))
    return cand[-1] if cand else None

# demand
rows=list(csv.DictReader(open('inbox/06-02/设备申请.csv',encoding='utf-8-sig')))
agg=defaultdict(lambda: defaultdict(list))
for r in rows: agg[r['案号']][r['设备序号']].append(r)
def demand(case):
    tot=0
    for dev,rs in agg[case].items():
        rs.sort(key=lambda x:int(x['修订号'])); mx=rs[-1]
        if mx['状态']!='取消': tot+=int(mx['申请席位'])
    return tot
def category(case):
    cs={r['服务类别'] for r in rows if r['案号']==case}
    assert len(cs)==1, (case,cs); return cs.pop()

# 凭证
voucher={}
for r in csv.DictReader(open('input/现场服务/凭证册.csv',encoding='utf-8-sig')):
    voucher[(r['主站'],r['服务类别'])]=r['凭证']

# capacity
cap={}
for r in csv.DictReader(open('input/现场服务/期初容量.csv',encoding='utf-8-sig')):
    if int(r['生效日'])<=2: cap[r['主站']]=cap.get(r['主站'],0)+int(r['增额'])
print('capacity',cap)

cases=[('P01','HZ-A'),('P02','HZ-B'),('P04','JL-B'),('P09','QH-A')]
prio={'P01':56,'P02':69,'P04':19,'P09':35}
# 换机时限
term={'HZ-A':'7个工作日','HZ-B':'10个工作日','JL-B':'5个工作日','QH-A':'10个工作日'}

info={}
for case,obj in cases:
    d=station_for(obj)
    st=d.station
    cat=category(case)
    info[case]=dict(obj=obj,station=st,voucher=voucher[(st,cat)],demand=demand(case),cat=cat,term=term[obj])

# allocate in priority order
order=sorted(info.keys(), key=lambda c:(prio[c],c))
remain=dict(cap)
reserved={}
for c in order:
    need=info[c]['demand']; st=info[c]['station']
    have=remain.get(st,0)
    if have>=need:
        reserved[c]=need; remain[st]=have-need
    else:
        reserved[c]=0
    print('alloc',c,info[c]['obj'],'站',st,'需',need,'余前',have,'-> 预留',reserved[c],'余后',remain[st])
for c in info: info[c]['reserved']=reserved[c]
print('remaining',remain)

# write markdown
os.makedirs('out/评审稿',exist_ok=True)
mail={'HZ':'hz.service@office.test','JL':'jl.service@office.test','QH':'qh.service@office.test'}
for case,obj in cases:
    i=info[case]
    code=obj.split('-')[0]
    content=f"""# 服务通告（六月版·评审稿） {case}

对象：{obj}
换机时限：{i['term']}
服务主站：{i['station']}
服务凭证：{i['voucher']}
预留席位：{i['reserved']}

适用：六月批次
保管人：{mail[code]}
"""
    open(f'out/评审稿/{case}.md','w',encoding='utf-8').write(content)
    print('wrote',case)

# summary json for later
import json
json.dump(info,open('notes/R2_附页演算.json','w',encoding='utf-8'),ensure_ascii=False,indent=2)
print(json.dumps(info,ensure_ascii=False,indent=2))
